#include "stdlib/math/base/special/exp10f.h"
#include "stdlib/math/base/special/floorf.h"
#include "stdlib/math/base/special/ldexpf.h"
#include "stdlib/math/base/assert/is_nanf.h"
#include "stdlib/constants/float32/max_base10_exponent.h"
#include "stdlib/constants/float32/min_base10_exponent.h"
#include "stdlib/constants/float32/pinf.h"
#include <stdint.h>

// log2(10) => 0 10000000 10101001001101001111000 => 0x40549A78 = 1079286392
static const float LOG210 = 3.32192809488736234787e0f;

// High part of log10(2) => 0 01111101 00110100000000000000000 => 0x3E9A0000 = 1050279936
static const float LG102A = 3.00781250000000000000e-1f;

// Low part of log10(2) => 0 01110011 00000100110101000010100 => 0x39826A14 = 964848148
static const float LG102B = 2.48745663981195213739e-4f;

// BEGIN: polyval_p

/**
* Evaluates a polynomial.
*
* ## Notes
*
* -   The implementation uses [Horner's rule][horners-method] for efficient computation.
*
* [horners-method]: https://en.wikipedia.org/wiki/Horner%27s_method
*
* @param x    value at which to evaluate the polynomial
* @return     evaluated polynomial
*/
static float polyval_p( const float x ) {
	return 2.302585167056758f + (x * (2.650948748208892f + (x * (2.034649854009453f + (x * (1.171292686296281f + (x * (0.5420251702225484f + (x * 0.2063216740311022f)))))))));
}

// END: polyval_p

/**
* Evaluates the base `10` exponential function in single-precision floating-point format.
*
* ## Method
*
* -   Range reduction is accomplished by expressing the argument as
*
*     ```tex
*     10^x = 2^n 10^f,
*     ```
*
*     where \\(|f| < \frac{1}{2}\log_{10}(2)\\).
*
* -   The fractional part \\(10^f\\) is approximated using a degree-5 polynomial.
*
* @param x    input value
* @return     function value
*
* @example
* float out = stdlib_base_exp10f( 2.0f );
* // returns 100.0f
*/
float stdlib_base_exp10f( const float x ) {
	float xx;
	float px;
	int32_t n;

	if ( stdlib_base_is_nanf( x ) ) {
		return x;
	}
	if ( x > STDLIB_CONSTANT_FLOAT32_MAX_BASE10_EXPONENT ) {
		return STDLIB_CONSTANT_FLOAT32_PINF;
	}
	if ( x < STDLIB_CONSTANT_FLOAT32_MIN_BASE10_EXPONENT ) {
		return 0.0f;
	}
	if ( x == 0.0f ) {
		return 1.0f;
	}
	// Express 10^x = 10^g * 2^n = 10^(g + n*log10(2)):
	px = x * LOG210;
	n = (int32_t)stdlib_base_floorf( px + 0.5f );

	xx = x;
	xx -= (float)n * LG102A;
	xx -= (float)n * LG102B;

	// Rational approximation for exponential of the fractional part:
	px = 1.0f + ( xx * polyval_p( xx ) );

	// Multiply by power of 2:
	return stdlib_base_ldexpf( px, n );
}
